useEffect(() => heroFlashController.dispose, [heroFlashController]);

// Linux-only: while horizontal scrubbing, show target/duration/progress on
// the bottom crumb line and clear it shortly after the gesture ends.
final seekCrumbLabel = useState<String?>(null);
final seekClearTimer = useRef<Timer?>(null);

void setSeekCrumb(int positionMs, int durationMs, double progress) {
  final label = durationMs <= 0
      ? '--:-- / --:-- (0%)'
      : '${formatClock(positionMs)} / ${formatClock(durationMs)} (${(progress * 100).round()}%)';
  seekClearTimer.value?.cancel();
  seekCrumbLabel.value = label;
}

void hideSeekCrumb() {
  seekClearTimer.value?.cancel();
  seekClearTimer.value = Timer(const Duration(milliseconds: 200), () {
    seekCrumbLabel.value = null;
  });
}

